    $runtime=dirname((string)getenv('KH_NATIVE_TEST_CONFIG')).'/runtime-'.\Kulturhus\Native\TestSupport::config()['database'];if(is_dir($runtime))throw new RuntimeException('Own fresh file API runtime already exists');mkdir($runtime,0700);foreach(['sessions','media']as$dir)mkdir($runtime.'/'.$dir,0700);copy($fixture['root'].'/auth.key',$runtime.'/auth.key');chmod($runtime.'/auth.key',0600);
